mapper.select:
SELECT IF(COUNT(user_id) > 0, 1, 0) AS `exists`
FROM users
WHERE login_id = #{loginId}

SELECT IF(COUNT(user_id) > 0, 1, 0) AS `exists`
FROM users
WHERE email = #{email}

SELECT login_id, 1 AS `exists`
FROM users
WHERE name = #{name}
  AND email = #{email}
LIMIT 1

SELECT user_id, login_id, name, email, 1 AS `exists`
FROM users
WHERE login_id = #{loginId}
  AND email = #{email}
LIMIT 1

mapper.update:
UPDATE users
SET password = #{password},
    salt = #{salt},
    updated_at = CURRENT_TIMESTAMP
WHERE login_id = #{loginId}
  AND email = #{email}
